import { mount } from 'svelte'
import './style.css'
import App from './App.svelte'
import { setLocale, detectLocale } from '$lib/i18n';

// @ts-expect-error — generated by Wails
import { GetUILocale, SetUILocale } from '@wails/go/gui/App.js';

// Detect OS locale on first launch
async function initLocale(): Promise<void> {
  try {
    const saved = await GetUILocale();
    if (saved) {
      setLocale(saved);
      return;
    }
  } catch {
    // No saved locale — detect from browser
  }
  const detected = await detectLocale();
  setLocale(detected);
  try { await SetUILocale(detected); } catch { /* ignore */ }
}

initLocale().then(() => {
  mount(App, {
    target: document.getElementById('app') as Element
  });
});
